package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.articles.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
/** Actual daily source/native original catalogue analysis plus complete zero NEWS/count universes. Source/model/settings genesis remains fictional. */
class ReportDailyPreparationIntegrationTest {
 boolean mysql(){return false;}
 DailyReportInputComponentTest f;ReportInputCaptureService.Scope scope;ReportPreparedInputService originals;ReportPreparationService service;
 void setup()throws Exception{f=new DailyReportInputComponentTest(){@Override boolean mysql(){return ReportDailyPreparationIntegrationTest.this.mysql();}};f.nativeSetup("agent");var base=f.data.nativeData().fixture().f();var capture=new ReportInputCaptureService(f.service,mock(ReportPeriodInputComponentService.class),base.tx);var admission=new ReportInputWriterAdmissionService(base.source,base.tx,capture);originals=new ReportPreparedInputService(base.source,base.tx);var members=new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(base.source));var metadata=new ReportPublicMetadataEnricher(new ArticlePublicEvidenceService(new JdbcArticlePublicEvidence(base.source),members),members,new FrozenContentVersionService(new JdbcFrozenContentVersions(base.source)));var day=f.data.nativeData().fixture().day();scope=new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day);service=new ReportPreparationService(base.source,originals,admission,base.writes,()->new FrozenGenerationSettings(1,List.of(),List.of()),metadata,new GenerationRequestBuilder(),Clock.fixed(f.data.nativeData().cutoff().plusNanos(123456000),ZoneOffset.UTC),()->true);}
 ReportPreparedInputService.Prepared prepare(){return ReportOriginalCompletionTest.utc(()->service.prepare(scope));}
 @Test void ActualOriginalDailyCatalogueBodyCreatesFullNativeRequestAndImmutablePublicCitations()throws Exception{setup();var prepared=prepare();var input=CanonicalJson.parse(prepared.input().snapshotJson());assertEquals("queued",prepared.input().state());assertEquals("complete",prepared.input().coverageState());assertEquals(1,input.get("members").size());assertEquals(CanonicalJson.parse(f.data.nativeData().completed().bodyJson()),input.get("members").get(0).get("body"));var profile=ReportPreparationInputProfile.complete(input);assertEquals(1,profile.command().applicationContext().referenceTargets().size());assertEquals(1,input.get(FrozenPublicMetadata.FIELD).get("citations").size());assertEquals("deepseek-flash",CanonicalJson.parse(prepared.input().requestJson()).get("model").asText());assertEquals(2,f.data.nativeData().fixture().f().sends);assertEquals(prepared,originals.find(scope));assertEquals(prepared,service.prepare(scope));}
 @Test void CompleteSourceWithOnlyBlockedInputStaysNativeNoInputWithNoAttemptOrInventedNoUpdateDate()throws Exception{setup();var base=f.data.nativeData().fixture().f();base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",f.data.nativeData().completed().version().contentId());var prepared=prepare();assertEquals("no_input",prepared.input().state());assertEquals("no_input",prepared.input().coverageState());assertNull(prepared.input().requestJson());var input=CanonicalJson.parse(prepared.input().snapshotJson());assertTrue(input.get("members").isEmpty());assertTrue(input.get(ReportInputProfile.FIELD).get("coverage").get("no_update_dates").isEmpty());assertTrue(input.get(FrozenPublicMetadata.FIELD).get("citations").isEmpty());assertEquals(0,new JdbcJobRecords(base.source).byId(prepared.input().ownerId()).callCount());assertEquals(0L,base.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='ai_attempt' AND root_job_id=?",Long.class,prepared.input().ownerId()));assertEquals(prepared,service.prepare(scope));assertEquals(2,base.sends);}
 @Test void AnAlreadyUsedTargetIdentityRejectsBeforeAnyNativeReportRootOrRequestIsPersisted()throws Exception{setup();var base=f.data.nativeData().fixture().f();String id=ReportPreparationService.contentId(scope);var baseline=new ReportPreparationContentBaselineService(base.source);base.writes.execute(base.action("fictional-report-existing-target"),k->null,a->{baseline.requireAbsent(id);return true;});assertThrows(RuntimeException.class,()->baseline.requireAbsent(id));base.jdbc.update("UPDATE contents SET id=? WHERE id=?",id,f.data.nativeData().completed().version().contentId());assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-existing-baseline-reject"),k->null,a->{baseline.requireAbsent(id);return true;}));assertThrows(RuntimeException.class,this::prepare);assertNull(originals.find(scope));assertEquals(2,base.sends);}
 @Test void MissingNativeOriginalVersionCannotBeReplacedByTheCurrentContentBody()throws Exception{setup();var base=f.data.nativeData().fixture().f();base.jdbc.update("DELETE FROM jobs WHERE target_type='content_availability'");var prepared=prepare();var input=CanonicalJson.parse(prepared.input().snapshotJson());assertEquals("no_input",prepared.input().state());assertNull(prepared.input().requestJson());assertTrue(input.get("members").isEmpty());assertTrue(input.get(FrozenPublicMetadata.FIELD).get("citations").isEmpty());var coverage=input.get(ReportInputProfile.FIELD).get("coverage");assertTrue(coverage.get("no_update_dates").isEmpty());assertTrue(coverage.get("missing_inputs").valueStream().anyMatch(v->"catalog_analysis".equals(v.path("kind").asText())&&"not_completed_at_cutoff".equals(v.path("reason").asText())));assertFalse(prepared.input().missing().isEmpty());assertEquals(prepared,originals.find(scope));assertEquals(0,new JdbcJobRecords(base.source).byId(prepared.input().ownerId()).callCount());assertEquals(2,base.sends);}
}
